{
  "wire_schema": "role_benchmark.player_action.v3",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H_std",
        "statement": "Period depends only on length as T = C * L^0.5; mass and release angle have no effect.",
        "confidence": 0.6
      },
      {
        "hypothesis_id": "H_mass_sqrt",
        "statement": "Period depends on length^0.5 and on bob_mass^0.5: T = C * L^0.5 * (M/0.20)^0.5.",
        "confidence": 0.2
      },
      {
        "hypothesis_id": "H_mass_lin",
        "statement": "Period depends on length^0.5 and linearly on bob_mass: T = C * L^0.5 * (M/0.20).",
        "confidence": 0.1
      },
      {
        "hypothesis_id": "H_lin_len",
        "statement": "Period depends linearly on length and is independent of mass: T = C * L.",
        "confidence": 0.1
      }
    ]
  },
  "experiment": {
    "intent": "Measure the period at L=1 m, M=0.8 kg, theta=5 deg to strongly discriminate mass-dependence hypotheses while establishing the baseline scale.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 1.0,
      "bob_mass_kg": 0.8,
      "release_angle_deg": 5.0
    },
    "readouts": [
      "period_s"
    ],
    "replicates": 20,
    "forecasts": {
      "H_std": {
        "period_s": 2.01
      },
      "H_mass_sqrt": {
        "period_s": 4.02
      },
      "H_mass_lin": {
        "period_s": 8.04
      },
      "H_lin_len": {
        "period_s": 2.01
      }
    }
  },
  "final": null
}

